targets.query:
import "math" // Εισαγωγή βιβλιοθήκης για στρογγυλοποίηση

from(bucket: "eap_plh40")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r["_measurement"] == "air_quality")
  |> filter(fn: (r) => r["id"] == "${NodeID}")
  |> filter(fn: (r) => r["_field"] == "v")
  |> last()
  |> map(fn: (r) => {
      // 1. Υπολογισμός Ποσοστού
      pct = if r._value >= 4.1 then 100.0
            else if r._value <= 3.0 then 0.0
            else (r._value - 3.0) / 1.1 * 100.0

      // 2. Στρογγυλοποίηση Volt σε 2 δεκαδικά (π.χ. 3.45)
      volts = math.round(x: r._value * 100.0) / 100.0

      // 3. Επιστροφή: Τιμή = Ποσοστό, Όνομα = "3.45 V"
      return {
          _time: r._time,
          _value: pct,
          _field: string(v: volts) + " V"
      }
  })

from(bucket: "eap_plh40")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r["_measurement"] == "air_quality")
  |> filter(fn: (r) => r["id"] == "${NodeID}")
  |> filter(fn: (r) => r["_field"] == "pkt")
  // ΣΗΜΑΝΤΙΚΟ: Μετατροπή σε ακέραιο (int) για αποφυγή προβλημάτων τύπου
  |> map(fn: (r) => ({ r with _value: int(v: r._value) }))
  |> group(columns: ["topic"]) 
  
  // Υπολογίζουμε min, max, count σε ένα πέρασμα
  |> reduce(
      identity: {count: 0, min: 0, max: 0, first: true},
      fn: (r, accumulator) => ({
        count: accumulator.count + 1,
        min: if accumulator.first then r._value else (if r._value < accumulator.min then r._value else accumulator.min),
        max: if accumulator.first then r._value else (if r._value > accumulator.max then r._value else accumulator.max),
        first: false
      })
  )
  
  // Κάνουμε τα μαθηματικά: Expected - Actual = Lost
  |> map(fn: (r) => {
      expected = r.max - r.min + 1
      lost = expected - r.count
      return {
        node: r.topic, 
        latest_seq: r.max, 
        total_lost: lost,
        // Υπολογισμός ποσοστού: (Lost / Expected) * 100
        loss_perc: if expected > 0 then (float(v: lost) / float(v: expected)) * 100.0 else 0.0
      }
  })
  
  |> drop(columns: ["min", "max", "count", "first"])
